/** A parsed range table: parallel arrays of first, last and value index. */
interface Parsed { lo: Uint32Array; hi: Uint32Array; v: Uint16Array }

/** Parse one range string. */
function parse(s: string): Parsed {
  // The numbers.
  const n = s.split(",");
  // The number of ranges.
  const k = n.length / 3;
  // The arrays.
  const p: Parsed = { lo: new Uint32Array(k), hi: new Uint32Array(k), v: new Uint16Array(k) };
  // Fill them.
  for (let i = 0; i < k; i++) { p.lo[i] = parseInt(n[3 * i], 16); p.hi[i] = parseInt(n[3 * i + 1], 16); p.v[i] = parseInt(n[3 * i + 2], 10); }
  // Done.
  return p;
}

/** The parsed tables, built on first use. */
const cache: Record<string, Parsed> = {};

/** The value of one table at a code point, or the fallback. */
function lookupIn(key: string, s: string, values: readonly string[], cp: number, fallback: string): string {
  // Parse once.
  const p = cache[key] ?? (cache[key] = parse(s));
  // Binary search.
  let lo = 0, hi = p.lo.length - 1;
  // Halve.
  while (lo <= hi) { const mid = (lo + hi) >> 1; if (cp < p.lo[mid]) hi = mid - 1; else if (cp > p.hi[mid]) lo = mid + 1; else return values[p.v[mid]]; }
  // Not covered.
  return fallback;
}

/** General_Category (two letters, such as Lu or Cc); Cn when unassigned. */
export function generalCategory(cp: number): string {
  // From UnicodeData.
  return lookupIn("gc", GC_RANGES, GC_VALUES, cp, "Cn");
}

/** Block name; "No_Block" outside every block. */
export function blockOf(cp: number): string {
  // From Blocks.txt.
  return lookupIn("block", BLOCK_RANGES, BLOCK_VALUES, cp, "No_Block");
}

/** The Unicode version that assigned the code point; "Unassigned" otherwise. */
export function ageOf(cp: number): string {
  // From DerivedAge.txt.
  return lookupIn("age", AGE_RANGES, AGE_VALUES, cp, "Unassigned");
}

/** Script; "Unknown" when the code point has none. */
export function scriptOf(cp: number): string {
  // From Scripts.txt.
  return lookupIn("script", SCRIPT_RANGES, SCRIPT_VALUES, cp, "Unknown");
}

/** Script_Extensions as four-letter codes (the Script's code when the file does not list the code point). */
export function scriptExtensionsOf(cp: number): string[] {
  // From ScriptExtensions.txt.
  const listed = lookupIn("scx", SCX_RANGES, SCX_VALUES, cp, "");
  // Listed: the codes; otherwise the Script's own code.
  return listed ? listed.split(" ") : [SCRIPT_CODE[scriptOf(cp)] ?? "Zzzz"];
}
